import unittest

from solucao import formatar


class TestFormatarComLargura(unittest.TestCase):
    def test_preenche_a_esquerda_com_espacos(self):
        """formatar alinha o valor a direita em 8 posicoes"""
        self.assertEqual(formatar(314), "    3.14")

    def test_fixa_duas_casas_decimais(self):
        """formatar completa a segunda casa decimal"""
        self.assertEqual(formatar(4250), "   42.50")

    def test_centavos_solteiros(self):
        """formatar mostra os centavos solteiros como centesimo de real"""
        self.assertEqual(formatar(7), "    0.07")

    def test_valor_grande_ocupa_a_largura_toda(self):
        """formatar devolve o valor inteiro quando ele ocupa a largura toda"""
        self.assertEqual(formatar(100000), " 1000.00")
